import pathlib,subprocess,tempfile,os,ssl,socket,hashlib,time,signal,json,stat
def rollout(nodes,certificate,private_key,ca_file,report_file):
    nodes=[dict(n,directory=pathlib.Path(n['directory']).resolve()) for n in nodes]
    certificate=pathlib.Path(certificate).resolve();private_key=pathlib.Path(private_key).resolve();ca_file=str(pathlib.Path(ca_file).resolve())
    # Validate the report destination before any node work or rejection report.
    root=pathlib.Path.cwd().resolve();requested=pathlib.Path(report_file);target=requested.resolve()
    protected=[certificate,private_key,pathlib.Path(ca_file)]
    directories=[n['directory'] for n in nodes]
    if requested.is_symlink() or not target.is_relative_to(root) or target==root or not target.parent.is_dir():
        raise ValueError('report must be a regular workspace destination')
    if target.exists() and not target.is_file():raise ValueError('report must be a file')
    if any(target==path or (target.exists() and path.exists() and os.path.samefile(target,path)) for path in protected):
        raise ValueError('report aliases protected certificate material')
    if any(target.is_relative_to(directory) for directory in directories):
        raise ValueError('report must be outside every node directory')
    report={'status':'rejected','nodes':[],'error':None}
    def command(args):
        return subprocess.run(args,capture_output=True,check=True,timeout=3).stdout
    def atomic(path,data,mode):
        fd,name=tempfile.mkstemp(prefix='.rollout-',dir=path.parent)
        try:
            with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
            os.chmod(name,mode);os.replace(name,path)
        finally:
            if os.path.exists(name):os.unlink(name)
    def fingerprint(pem):
        return hashlib.sha256(ssl.PEM_cert_to_DER_cert(pem.decode())).hexdigest()
    def probe(node):
        ctx=ssl.create_default_context(cafile=ca_file)
        with socket.create_connection(('127.0.0.1',node['port']),timeout=1) as raw:
            with ctx.wrap_socket(raw,server_hostname='lab.test') as conn:
                digest=hashlib.sha256(conn.getpeercert(binary_form=True)).hexdigest()
                conn.sendall(b'GET / HTTP/1.1\r\nHost: lab.test\r\nConnection: close\r\n\r\n')
                first=b''
                while b'\r\n' not in first:
                    chunk=conn.recv(1024)
                    if not chunk:raise RuntimeError('empty HTTP response')
                    first+=chunk
                if first.split(b'\r\n',1)[0]!=b'HTTP/1.1 200 OK':raise RuntimeError('application unhealthy')
                return digest
    def activate(node,digest):
        directory=node['directory']
        command(['nginx','-p',str(directory)+'/', '-c',str(directory/'nginx.conf'),'-t'])
        os.kill(node['pid'],signal.SIGHUP)
        deadline=time.monotonic()+3;last=None;stable=0
        while time.monotonic()<deadline:
            try:
                last=probe(node)
                stable=stable+1 if last==digest else 0
                if stable>=5:return
            except (OSError,ssl.SSLError,RuntimeError) as error:last=type(error).__name__;stable=0
            time.sleep(.05)
        raise RuntimeError('node did not activate expected certificate: '+str(last))
    snapshots={};changed=[]
    try:
        if not nodes or len({n['name'] for n in nodes})!=len(nodes):raise ValueError('nodes must have unique names')
        command(['openssl','verify','-CAfile',ca_file,'-verify_hostname','lab.test',str(certificate)])
        command(['openssl','x509','-checkend','60','-noout','-in',str(certificate)])
        cert_public=command(['openssl','x509','-in',str(certificate),'-pubkey','-noout'])
        key_public=command(['openssl','pkey','-in',str(private_key),'-pubout'])
        if cert_public!=key_public:raise ValueError('certificate/private key mismatch')
        cert_bytes=certificate.read_bytes();key_bytes=private_key.read_bytes();expected=fingerprint(cert_bytes)
        for node in nodes:
            directory=node['directory'];saved={}
            for name in ['tls.crt','tls.key']:
                path=directory/name;saved[name]=(path.read_bytes(),stat.S_IMODE(path.stat().st_mode))
            saved['fingerprint']=fingerprint(saved['tls.crt'][0])
            command(['nginx','-p',str(directory)+'/', '-c',str(directory/'nginx.conf'),'-t'])
            if probe(node)!=saved['fingerprint']:raise RuntimeError('disk/live certificate mismatch')
            snapshots[node['name']]=saved
        for node in nodes:
            changed.append(node)
            atomic(node['directory']/'tls.key',key_bytes,0o600)
            atomic(node['directory']/'tls.crt',cert_bytes,0o644)
            activate(node,expected)
            report['nodes'].append({'name':node['name'],'before':snapshots[node['name']]['fingerprint'],'after':expected})
        report['status']='committed'
    except Exception as error:
        report['error']=type(error).__name__
        if changed:
            failures=[];report['restored_nodes']=[]
            for node in reversed(changed):
                try:
                    saved=snapshots[node['name']]
                    for name in ['tls.key','tls.crt']:
                        path=node['directory']/name;data,mode=saved[name]
                        if path.read_bytes()!=data or stat.S_IMODE(path.stat().st_mode)!=mode:atomic(path,data,mode)
                    activate(node,saved['fingerprint'])
                    report['restored_nodes'].append({'name':node['name'],'fingerprint':saved['fingerprint']})
                except Exception as recovery:failures.append({'name':node['name'],'error':type(recovery).__name__})
            report['status']='rollback_failed' if failures else 'rolled_back'
            report['rollback_errors']=failures
    target=pathlib.Path(report_file).resolve()
    atomic(target,(json.dumps(report,sort_keys=True)+'\n').encode(),0o600)
    return report

